VCS Unreachability Analysis (UNR)
Use Model
Consider the following example:
module test (output reg rd, ds, input go, ws, clk, rst_n);
parameter IDLE = 2'b00,READ = 2'b01,DLY = 2'b11,DONE = 2'b10;
reg [1:0] state;
always @(posedge clk or negedge rst_n)
begin
if (!rst_n)
begin
state <= IDLE;
rd <= 1'b0;
ds <= 1'b0;
end
else
begin
rd <= 1'b0;
ds <= 1'b0;
case (state)
IDLE : if (go) begin
rd <= 1'b1;
state <= READ;
end
else state <= IDLE;
READ : begin
rd <= 1'b1;
if (!go)
state <= DLY;
end
DLY : if (!ws) begin
ds <= 1'b1;
state <= READ;
end
else begin
rd <= 1'b1;
state <= IDLE;
end
DONE : state <= IDLE;
endcase
end
end
endmodule
