module:
function myFn(input reg arg);
automatic reg a,b,c;
if ( arg == 1'b0 )
myFn = a;
myFn = b;
endfunction;
function myFn2(input reg arg);
automatic reg a,b,c;
if ( (arg && a) || b )
myFn2 = a;
myFn2 = b;
endfunction;

