entity RAM is
generic (n_addr : natural; n_data : natural);
port (addr : in std_logic_vector(n_addr - 1 downto 0);
datain : in std_logic_vector(n_data - 1 downto 0);
dataout : out std_logic_vector(n_data - 1 downto 0);
rw : in std_logic
clk : in std_logic );
architecture CYCLONE of RAM is
signal handle : memHandle := mem_init(MK_RAM, n_addr, n_data);

READER_WRITER: process (clk)
variable v : std_logic_vector(n_data - 1 downto 0);
if (clk'event and clk = '1') then
if (rw = '0') then
mem_write(handle, addr, datain);
mem_read(handle, addr, v);
dataout <= v;
Dual Port Memories
The guidelines for effectively modeling dual port memories in VCS cycle are provided in
this section.

Dual Port Memories
If the memory functionality checks for simultaneous read/write or write/write conflicts
between the two ports to the same address, model this functionality with a single process.
This process references two clocks, two enables, and so on. Thus, it is simulated as a
testbench process.
Do not use the 'Event attribute except as permitted for sequential coding guidelines.
Specifically, do not use the 'Event attribute to perform read/write or write/write conflict
checks in multi-port memory models. Instead, model the conflict checks as shown in
Example 37.
Example 37 Dual Port RAM Modeling with Read/Write Conflict Checks
architecture behave of dual_port_ram is
type ram_type is array(0 to 2**addr_bits) of word;

read_write : process(rsta, clka, rstb, clkb)
variable ram : ram_type;
variable address : Natural;
variable porta_read : Boolean;
variable porta_write : Boolean;
porta_read := FALSE;
porta_write := FALSE;

if rsta = '1' then
data_outa <= (others => '0');
elsif clka'event and clka = '1' then
if wea = '1' then
address := to_integer(addra);
ram(address) := data_ina;
porta_write := TRUE;
if (wea = '1') or (ena = '1') then
address := to_integer(addra);
data_outa <= ram(address);
porta_read := TRUE;

if rstb = '1' then
data_outb <= (others => '0');
elsif clkb'event and clkb = '1' then
if web = '1' then
if porta_read and addra = addrb then
data_outa <= (others => 'X');
address := to_integer(addrb);

