void foreignProc(vhpiCbDataT* pCbData)
{
vhpiHandleT procedure;
vhpiHandleT parameters, parameter;

procedure = pCbData->obj;
vhpi_printf("procedure name = <%s>\n",
vhpi_get_str(vhpiNameP, procedure));

parameters = vhpi_iterator(vhpiParamDecls, procedure);
while (parameter = vhpi_scan(parameters))
{
char kindstr[256];
char typestr[256];

vhpiHandleT type = vhpi_handle(vhpiSubtype, parameter);
vhpiHandleT basetype = vhpi_handle(vhpiBaseType, type);

strcpy(kindstr, vhpi_get_str(vhpiKindStrP, parameter));
strcpy(typestr, vhpi_get_str(vhpiNameP, basetype));

vhpi_printf("%s %s is of basetype %s\n",
kindstr, vhpi_get_str(vhpiNameP, parameter), typestr);

vhpi_release_handle(basetype);
vhpi_release_handle(type);
}
vhpi_release_handle(parameters);
}
