int find_cbk(vhpiHandleT objHdl)
{
vhpiHandleT cbHdl, cbItr;
vhpiCbDataT cbdata;
int found = 0;
/* find a specific callback on value change
that was registered for object and remove it */
cbItr = vhpi_iterator(vhpiCallbacks, objHdl);
if (!cbItr) return;
while (cbHdl = vhpi_scan(cbItr))
{
vhpi_get_cb_info(cbHdl, &cbdata);
if ((int)(cbdata.user_data) == 2)
{
vhpi_remove_cb(cbHdl);
found = 1;
break;
}
}
vhpi_release_handle(cbItr); /* free the iterator */
return(found);
}

